      var names = { role: '角色', employee: '员工', area: '订单区域', orderType: '订单类型', menu: '菜单', revenueType: '营业额', orderTipStatus: '订单小费状态', paymentMethods: '支付方式', hours: '营业时间', shift: '班次', weekday: '周期（星期）' };
